CREATE TABLE `backup_records` (`id` integer PRIMARY KEY AUTOINCREMENT,`uuid` text,`filename` text NOT NULL,`size` integer,`sha256` text,`type` text,`format_version` integer DEFAULT 2,`encrypted` numeric DEFAULT false,`app_version` text,`status` text,`error_message` text,`created_at` datetime,`updated_at` datetime);
