CREATE TABLE `backup_remote_copies` (`id` integer PRIMARY KEY AUTOINCREMENT,`backup_record_id` integer NOT NULL,`remote_target_id` integer NOT NULL,`remote_key` text,`status` text,`error_message` text,`uploaded_at` datetime,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_backup_remote_copies_remote_target` FOREIGN KEY (`remote_target_id`) REFERENCES `remote_storage_targets`(`id`),CONSTRAINT `fk_backup_records_remote_copies` FOREIGN KEY (`backup_record_id`) REFERENCES `backup_records`(`id`));
